### Objective
Build a production-grade Real-Time Stock Market & Trading Terminal demonstrating strict Event-Driven BLoC architecture, custom concurrency transformers (droppable for order executions and restartable for debounced stock lookups), immutable state unions with Equatable, and comprehensive transition auditing.

```dart
import 'dart:async';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:bloc_concurrency/bloc_concurrency.dart';
import 'package:equatable/equatable.dart';

void main() {
  Bloc.observer = TerminalBlocObserver();
  runApp(const TradingTerminalApp());
}

/// Global Telemetry and Audit Observer
class TerminalBlocObserver extends BlocObserver {
  @override
  void onEvent(BlocBase bloc, Object? event) {
    super.onEvent(bloc, event);
    debugPrint('📥 [${bloc.runtimeType}] Event Added: ${event.runtimeType}');
  }

  @override
  void onTransition(Bloc bloc, Transition transition) {
    super.onTransition(bloc, transition);
    debugPrint('🔀 [${bloc.runtimeType}] Transition: Event ${transition.event.runtimeType} | Current: ${transition.currentState.runtimeType} -> Next: ${transition.nextState.runtimeType}');
  }

  @override
  void onError(BlocBase bloc, Object error, StackTrace stackTrace) {
    debugPrint('🚨 [${bloc.runtimeType}] Fatal Error: $error');
    super.onError(bloc, error, stackTrace);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 1. DOMAIN MODELS & IMMUTABLE DATA
// ─────────────────────────────────────────────────────────────────────────────

class StockAsset extends Equatable {
  final String symbol;
  final String companyName;
  final double currentPrice;
  final double changePercent;

  const StockAsset({
    required this.symbol,
    required this.companyName,
    required this.currentPrice,
    required this.changePercent,
  });

  @override
  List<Object?> get props => [symbol, companyName, currentPrice, changePercent];
}

// ─────────────────────────────────────────────────────────────────────────────
// 2. FORMAL BLOC EVENTS
// ─────────────────────────────────────────────────────────────────────────────

sealed class TradingEvent extends Equatable {
  const TradingEvent();
  @override
  List<Object?> get props => [];
}

/// Dispatched when user types in the search query (uses restartable transformer)
class SearchStockQueryChanged extends TradingEvent {
  final String query;
  const SearchStockQueryChanged(this.query);
  @override
  List<Object?> get props => [query];
}

/// Dispatched when user clicks to buy stock (uses droppable transformer)
class ExecuteOrderRequested extends TradingEvent {
  final String symbol;
  final int shares;
  final double price;

  const ExecuteOrderRequested({
    required this.symbol,
    required this.shares,
    required this.price,
  });

  @override
  List<Object?> get props => [symbol, shares, price];
}

/// Resets terminal notification banner
class ClearOrderNotification extends TradingEvent {}

// ─────────────────────────────────────────────────────────────────────────────
// 3. FORMAL BLOC STATES
// ─────────────────────────────────────────────────────────────────────────────

sealed class TradingState extends Equatable {
  const TradingState();
  @override
  List<Object?> get props => [];
}

class TradingInitial extends TradingState {}

class TradingSearching extends TradingState {}

class TradingLoaded extends TradingState {
  final List<StockAsset> searchResults;
  final double userPortfolioBalance;
  final bool isOrderProcessing;
  final String? notificationBanner;

  const TradingLoaded({
    required this.searchResults,
    required this.userPortfolioBalance,
    this.isOrderProcessing = false,
    this.notificationBanner,
  });

  TradingLoaded copyWith({
    List<StockAsset>? searchResults,
    double? userPortfolioBalance,
    bool? isOrderProcessing,
    String? notificationBanner,
    bool clearBanner = false,
  }) {
    return TradingLoaded(
      searchResults: searchResults ?? this.searchResults,
      userPortfolioBalance: userPortfolioBalance ?? this.userPortfolioBalance,
      isOrderProcessing: isOrderProcessing ?? this.isOrderProcessing,
      notificationBanner: clearBanner ? null : (notificationBanner ?? this.notificationBanner),
    );
  }

  @override
  List<Object?> get props => [searchResults, userPortfolioBalance, isOrderProcessing, notificationBanner];
}

class TradingFailure extends TradingState {
  final String message;
  const TradingFailure(this.message);
  @override
  List<Object?> get props => [message];
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. ENTERPRISE BLOC WITH CONCURRENCY TRANSFORMERS
// ─────────────────────────────────────────────────────────────────────────────

class TradingBloc extends Bloc<TradingEvent, TradingState> {
  // Mock In-Memory Stock Catalog
  static const List<StockAsset> _allStocks = [
    StockAsset(symbol: 'GOOGL', companyName: 'Alphabet Inc.', currentPrice: 182.40, changePercent: 1.85),
    StockAsset(symbol: 'AAPL', companyName: 'Apple Inc.', currentPrice: 228.15, changePercent: -0.42),
    StockAsset(symbol: 'MSFT', companyName: 'Microsoft Corporation', currentPrice: 425.80, changePercent: 0.95),
    StockAsset(symbol: 'NVDA', companyName: 'NVIDIA Corporation', currentPrice: 119.50, changePercent: 3.40),
    StockAsset(symbol: 'AMZN', companyName: 'Amazon.com Inc.', currentPrice: 186.20, changePercent: -1.10),
  ];

  TradingBloc()
      : super(const TradingLoaded(
          searchResults: _allStocks,
          userPortfolioBalance: 25000.00,
        )) {
    // 1. RESTARTABLE TRANSFORMER: Cancels ongoing search on new keystroke!
    on<SearchStockQueryChanged>(
      _onSearchChanged,
      transformer: restartable(),
    );

    // 2. DROPPABLE TRANSFORMER: Drops duplicate clicks during trade processing!
    on<ExecuteOrderRequested>(
      _onExecuteOrder,
      transformer: droppable(),
    );

    on<ClearOrderNotification>((event, emit) {
      if (state is TradingLoaded) {
        emit((state as TradingLoaded).copyWith(clearBanner: true));
      }
    });
  }

  Future<void> _onSearchChanged(
    SearchStockQueryChanged event,
    Emitter<TradingState> emit,
  ) async {
    if (state is! TradingLoaded) return;
    final current = state as TradingLoaded;

    // Simulate debounce delay and network latency
    await Future.delayed(const Duration(milliseconds: 300));

    final query = event.query.trim().toLowerCase();
    if (query.isEmpty) {
      emit(current.copyWith(searchResults: _allStocks));
      return;
    }

    final filtered = _allStocks.where((s) {
      return s.symbol.toLowerCase().contains(query) ||
          s.companyName.toLowerCase().contains(query);
    }).toList();

    emit(current.copyWith(searchResults: filtered));
  }

  Future<void> _onExecuteOrder(
    ExecuteOrderRequested event,
    Emitter<TradingState> emit,
  ) async {
    if (state is! TradingLoaded) return;
    final current = state as TradingLoaded;

    final totalCost = event.price * event.shares;
    if (totalCost > current.userPortfolioBalance) {
      emit(current.copyWith(
        notificationBanner: 'Order rejected: Insufficient portfolio liquidity!',
      ));
      return;
    }

    // Set in-progress state
    emit(current.copyWith(isOrderProcessing: true));

    // Simulate exchange execution delay (1.5 seconds)
    // Any duplicate clicks during this window are DROPPED by droppable()!
    await Future.delayed(const Duration(milliseconds: 1500));

    emit(current.copyWith(
      userPortfolioBalance: current.userPortfolioBalance - totalCost,
      isOrderProcessing: false,
      notificationBanner: 'Order Filled: Bought ${event.shares}x ${event.symbol} for \$${totalCost.toStringAsFixed(2)}',
    ));
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. PRESENTATION LAYER
// ─────────────────────────────────────────────────────────────────────────────

class TradingTerminalApp extends StatelessWidget {
  const TradingTerminalApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'BLoC Trading Terminal',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        colorSchemeSeed: Colors.blueGrey,
        brightness: Brightness.dark,
        useMaterial3: true,
      ),
      home: BlocProvider(
        create: (context) => TradingBloc(),
        child: const TradingTerminalScreen(),
      ),
    );
  }
}

class TradingTerminalScreen extends StatelessWidget {
  const TradingTerminalScreen({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Institutional Trading Hub'),
        centerTitle: true,
        bottom: PreferredSize(
          preferredSize: const Size.fromHeight(64),
          child: Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16.0, vertical: 8.0),
            child: SearchBar(
              hintText: 'Search ticker symbol or company...',
              leading: const Icon(Icons.search),
              onChanged: (val) {
                // Dispatches Event to BLoC
                context.read<TradingBloc>().add(SearchStockQueryChanged(val));
              },
            ),
          ),
        ),
      ),
      body: BlocConsumer<TradingBloc, TradingState>(
        listener: (context, state) {
          if (state is TradingLoaded && state.notificationBanner != null) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(state.notificationBanner!),
                backgroundColor: state.notificationBanner!.startsWith('Order rejected')
                    ? Colors.redAccent
                    : Colors.green.shade700,
                behavior: SnackBarBehavior.floating,
              ),
            );
            context.read<TradingBloc>().add(ClearOrderNotification());
          }
        },
        builder: (context, state) {
          return switch (state) {
            TradingInitial() => const Center(child: CircularProgressIndicator()),
            TradingSearching() => const Center(child: CircularProgressIndicator()),
            TradingFailure(:final message) => Center(child: Text('Error: $message')),
            TradingLoaded(
              :final searchResults,
              :final userPortfolioBalance,
              :final isOrderProcessing
            ) =>
              ListView(
                padding: const EdgeInsets.all(16.0),
                children: [
                  _PortfolioHeaderCard(
                    balance: userPortfolioBalance,
                    isProcessing: isOrderProcessing,
                  ),
                  const SizedBox(height: 20),
                  Text(
                    'Market Listings',
                    style: Theme.of(context).textTheme.titleMedium?.copyWith(
                          fontWeight: FontWeight.bold,
                        ),
                  ),
                  const SizedBox(height: 12),
                  if (searchResults.isEmpty)
                    const Padding(
                      padding: EdgeInsets.only(top: 40),
                      child: Center(
                        child: Text('No assets match your search criteria.'),
                      ),
                    )
                  else
                    ...searchResults.map(
                      (stock) => _StockTradingTile(
                        stock: stock,
                        isProcessing: isOrderProcessing,
                      ),
                    ),
                ],
              ),
          };
        },
      ),
    );
  }
}

class _PortfolioHeaderCard extends StatelessWidget {
  final double balance;
  final bool isProcessing;

  const _PortfolioHeaderCard({
    required this.balance,
    required this.isProcessing,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: Theme.of(context).colorScheme.surfaceContainerHigh,
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: Colors.white12),
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text('Portfolio Buying Power', style: TextStyle(color: Colors.white60, fontSize: 13)),
              const SizedBox(height: 6),
              Text(
                '\$${balance.toStringAsFixed(2)}',
                style: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold, color: Colors.greenAccent),
              ),
            ],
          ),
          if (isProcessing)
            const Row(
              children: [
                SizedBox(width: 18, height: 18, child: CircularProgressIndicator(strokeWidth: 2)),
                SizedBox(width: 10),
                Text('Executing Order...', style: TextStyle(fontSize: 12, color: Colors.amberAccent)),
              ],
            ),
        ],
      ),
    );
  }
}

class _StockTradingTile extends StatelessWidget {
  final StockAsset stock;
  final bool isProcessing;

  const _StockTradingTile({
    required this.stock,
    required this.isProcessing,
  });

  @override
  Widget build(BuildContext context) {
    final isPositive = stock.changePercent >= 0;
    return Card(
      margin: const EdgeInsets.only(bottom: 10),
      color: Theme.of(context).colorScheme.surfaceContainerLow,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      child: ListTile(
        title: Text(stock.symbol, style: const TextStyle(fontWeight: FontWeight.bold)),
        subtitle: Text(stock.companyName, style: const TextStyle(fontSize: 12, color: Colors.white70)),
        trailing: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.end,
              children: [
                Text('\$${stock.currentPrice.toStringAsFixed(2)}', style: const TextStyle(fontWeight: FontWeight.w600)),
                Text(
                  '${isPositive ? '+' : ''}${stock.changePercent.toStringAsFixed(2)}%',
                  style: TextStyle(
                    fontSize: 12,
                    color: isPositive ? Colors.greenAccent : Colors.redAccent,
                  ),
                ),
              ],
            ),
            const SizedBox(width: 12),
            FilledButton.tonal(
              onPressed: isProcessing
                  ? null
                  : () {
                      // Dispatches Buy Order Event
                      context.read<TradingBloc>().add(
                            ExecuteOrderRequested(
                              symbol: stock.symbol,
                              shares: 10,
                              price: stock.currentPrice,
                            ),
                          );
                    },
              child: const Text('Buy 10'),
            ),
          ],
        ),
      ),
    );
  }
}
```

### Step-by-Step Code Walkthrough

1. **Strict Event Dispatches via context.read<TradingBloc>().add(...)**:
   Notice that the UI never calls internal methods on `TradingBloc`. The search bar dispatches `SearchStockQueryChanged(query)` and the Buy button dispatches `ExecuteOrderRequested(...)`.
2. **The restartable() Search Transformer**:
   In `TradingBloc`, `on<SearchStockQueryChanged>` is configured with `transformer: restartable()`. When a user types fast ("A", "AP", "APP", "AAPL"), each keystroke cancels the preceding in-flight filtering timer immediately, avoiding out-of-order search results.
3. **The droppable() Order Protection Transformer**:
   `on<ExecuteOrderRequested>` uses `transformer: droppable()`. If a user rapidly taps "Buy 10" four times while the 1.5-second execution delay is running, BLoC drops events 2, 3, and 4 completely, making double-charge bugs structurally impossible.
4. **Comprehensive State Transition Auditing**:
   `TerminalBlocObserver` overrides `onTransition`. Whenever a state change occurs, the console prints the exact event that caused it alongside the before and after states.

optimization:
## 1. Always Attach Concurrency Transformers to Critical Event Handlers

Never rely on manual boolean flags (such as `bool _isLoading = false`) inside event handlers to prevent duplicate submissions. Use `droppable()` from `package:bloc_concurrency`. It guarantees that the event is discarded at the stream subscription level before entering your business logic handler.

## 2. Clean Up Stream Subscriptions in close()

If your BLoC subscribes to external reactive streams (e.g. WebSocket price tickers, location sensors, Firebase snapshot streams), always store the `StreamSubscription` and cancel it inside the overridden `close()` method:

```dart
@override
Future<void> close() {
  _priceSubscription?.cancel();
  return super.close();
}
```

## 3. Leverage Dart 3 Sealed Classes for Exhaustive Pattern Matching

Using `sealed class TradingState` guarantees at compile-time that every state variation is handled in `switch (state)` expressions inside `BlocBuilder`. If a new state subclass is added in the future, the Dart compiler will immediately flag unhandled cases without waiting for runtime test failures.
